const failed = checks.filter((c) => !c.pass);
if (!checks[checks.length - 1].pass) throw new Error('Kiểm duyệt chặn bài: có số tiền, % khác 25%, cam kết điểm, số liệu học viên hoặc khan hiếm giả. Bài KHÔNG được đăng.');
